patch:
diff --git a/tmp-repro/repro.js b/tmp-repro/repro.js
new file mode 100644
index 0000000..ac970ef
--- /dev/null
+++ b/tmp-repro/repro.js
@@ -0,0 +1,32 @@
+"use strict";
+/*
+ * Reproduction for no-var autofix moving nothing but turning `var` into `let`
+ * when the variable is read before its declaration (TDZ ReferenceError).
+ * Usage: node tmp-repro/repro.js [path-to-eslint-package]   (default: this checkout)
+ */
+const path = require("node:path");
+const target = process.argv[2] ? path.resolve(process.argv[2]) : path.join(__dirname, "..");
+const { Linter } = require(path.join(target, "lib/api"));
+const version = require(path.join(target, "package.json")).version;
+const linter = new Linter({ configType: "flat" });
+
+const code = "export function a() {\n    console.log(o);\n    var o;\n    return o;\n}\n";
+const config = { rules: { "no-var": "error" }, languageOptions: { sourceType: "module" } };
+
+console.log(`eslint ${version}`);
+console.log("messages:", linter.verify(code, config).map(m => `${m.line}:${m.column} ${m.message} (${m.ruleId})${m.fix ? " [fixable]" : ""}`));
+const { fixed, output } = linter.verifyAndFix(code, config);
+console.log(`fixed=${fixed}\n${output}`);
+
+const run = src => {
+  const logs = [];
+  try {
+    new Function("console", src.replace(/^export /, "") + "\nreturn a();")({ log: v => logs.push(v) });
+    return `OK (logged ${JSON.stringify(logs.map(String))})`;
+  } catch (e) { return `${e.constructor.name}: ${e.message}`; }
+};
+console.log("original runs:", run(code));
+const result = run(output);
+console.log("fixed runs:   ", result);
+if (result.startsWith("ReferenceError")) { console.log("BUG REPRODUCED: no-var autofix introduced a TDZ ReferenceError"); process.exitCode = 1; }
+else console.log("bug not reproduced");
